22	#################################
23	{{- if and .Values.apiServer.enabled (semverCompare ">=3.0.0" .Values.airflowVersion) (or .Values.ingress.apiServer.enabled .Values.ingress.enabled) }}
24	{{- $fullname := include "airflow.fullname" . }}
25	apiVersion: networking.k8s.io/v1
26	kind: Ingress
27	metadata:
28	  name: {{ $fullname }}-ingress
29	  labels:
30	    tier: airflow
31	    component: airflow-ingress
32	    release: {{ .Release.Name }}
33	    chart: "{{ .Chart.Name }}-{{ .Chart.Version }}"
34	    heritage: {{ .Release.Service }}
35	    {{- if or .Values.labels .Values.apiServer.labels }}
36	      {{- mustMerge .Values.apiServer.labels .Values.labels | toYaml | nindent 4 }}
37	    {{- end }}
38	  {{- with .Values.ingress.apiServer.annotations }}
39	  annotations: {{- toYaml . | nindent 4 }}
40	  {{- end }}
41	spec:
42	  {{- if and .Values.ingress.apiServer.hosts (.Values.ingress.apiServer.hosts | first | kindIs "string" | not) }}
43	  {{- $anyTlsHosts := false -}}
44	  {{- range .Values.ingress.apiServer.hosts }}
45	  {{- if and .tls .tls.enabled }}
46	  {{- $anyTlsHosts = true -}}
47	  {{- end }}
48	  {{- end }}
49	  {{- if $anyTlsHosts }}
50	  tls:
51	  {{- range .Values.ingress.apiServer.hosts }}
52	  {{- if and .tls .tls.enabled }}
53	    - hosts:
54	        - {{ tpl .name $ | quote }}
55	      secretName: {{ .tls.secretName }}
56	  {{- end }}
57	  {{- end }}
58	  {{- end }}
59	  {{- else if .Values.ingress.apiServer.tls.enabled }}
60	  tls:
61	    - hosts:
62	        {{- range .Values.ingress.apiServer.hosts | default (list .Values.ingress.apiServer.host) }}
63	        - {{ tpl . $ | quote }}
64	        {{- end }}
65	      secretName: {{ .Values.ingress.apiServer.tls.secretName }}
66	  {{- end }}
67	  rules:
68	    {{- range .Values.ingress.apiServer.hosts | default (list .Values.ingress.apiServer.host) }}
69	    - http:
70	        paths:
71	          {{- range $.Values.ingress.apiServer.precedingPaths }}
72	          - path: {{ .path }}
73	            pathType: {{ .pathType }}
74	            backend:
75	              service:
76	                name: {{ $fullname }}-api-server
77	                port:
78	                  name: {{ .servicePort }}
79	          {{- end }}
80	          - backend:
81	              service:
82	                name: {{ $fullname }}-api-server
83	                port:
84	                  name: api-server
85	            {{- if $.Values.ingress.apiServer.path }}
86	            path: {{ $.Values.ingress.apiServer.path }}
87	            pathType: {{ $.Values.ingress.apiServer.pathType }}
88	            {{- end }}
89	          {{- range $.Values.ingress.apiServer.succeedingPaths }}
90	          - path: {{ .path }}
91	            pathType: {{ .pathType }}
92	            backend:
93	              service:
94	                name: {{ $fullname }}-api-server
95	                port:
96	                  name: {{ .servicePort }}
97	          {{- end }}
98	      {{- $hostname := . -}}
99	      {{- if . | kindIs "string" | not }}
100	        {{- $hostname = .name -}}
101	      {{- end }}
102	      {{- if $hostname }}
103	      host: {{ tpl $hostname $ | quote }}
104	      {{- end }}
105	    {{- end }}
106	  {{- if .Values.ingress.apiServer.ingressClassName }}
107	  ingressClassName: {{ .Values.ingress.apiServer.ingressClassName }}
108	  {{- end }}
109	{{- end }}
